css:
.p1 {
  font-family: "Cursive", Times, serif;
  text-align: center;
  font-size: 85px;
}
.p2{
    /*padding: 5px;*/
    font-family: "Georgia", Times, serif;
    text-align: center;
    font-size: 35px;

}

.p3 {
    font-family:"Cursive", Times,serif;
    /*margin-top: 40px;*/
    font-size: 35px;
    text-align: center;
}

.p4 {
    font-size: 90px;
    /*margin: 90px 0;*/
    text-align:center;
    font-family: 'Cursive', Times, serif;
}
.certificate-description {

    font-size: 18px;
    font-family: "Cursive", Times, serif;
    text-align: center;
}
.certificate-seal img {
  display: block;
  margin-left: auto;
  margin-right: auto;
  width: 25%;

}

.certificate-signatures {
    display: flex;
    justify-content: space-around;
    margin-top: 40px;
}

.signature-block {
    text-align: center;
}

.signature-line {
    border-top: 1px solid #000;
    width: 200px;
    margin: auto;
    margin-bottom: 5px;
}

.signature-name {
    margin: 5px 0;
    font-weight: bold;
}

.signature-role {
    margin: 0;
}
.print-format{
    background-color: #fffdd0;;
}
